import java.util.*;

class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        int n = bloomDay.length;
        if ((long) m * k > n) return -1;            // not enough flowers ever
        int lo = Integer.MAX_VALUE, hi = 0;
        for (int d : bloomDay) { lo = Math.min(lo, d); hi = Math.max(hi, d); }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (bunches(bloomDay, mid, k) >= m) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private int bunches(int[] bloomDay, int day, int k) {
        int count = 0, run = 0;
        for (int d : bloomDay) {
            if (d <= day) {
                run++;
                if (run == k) { count++; run = 0; } // one full bunch
            } else {
                run = 0;                              // closed flower breaks the run
            }
        }
        return count;
    }
}

