        if m * k > len(bloomDay): return -1
        def bunches(day):
            b = run = 0
            for d in bloomDay:
                run = run + 1 if d <= day else 0
                if run == k: b, run = b + 1, 0
            return b
        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if bunches(mid) >= m: hi = mid
            else: lo = mid + 1
        return lo

