function minDays(bloomDay, m, k) {
  if (m * k > bloomDay.length) return -1;
  const days = [...new Set(bloomDay)].sort((a, b) => a - b);
  const ok = (day) => { let b = 0, r = 0; for (const d of bloomDay) { if (d <= day) { if (++r === k) { b++; r = 0; } } else r = 0; } return b >= m; };
  let lo = 0, hi = days.length - 1;
  while (lo < hi) { const md = (lo + hi) >> 1; if (ok(days[md])) hi = md; else lo = md + 1; }
  return days[lo];
}
